import React from 'react';
import './ProfessorDetails.css';


function Review(props) {
    const {review} = props
    return (
        <>
            <div>
                {review.map((x) => {
                    return (<div className={"professor-evaluation"}>
                        <p>{x.title}: {'\t'&& Math.round(x.value)}</p>
                    </div>)
                })}
            </div>

        </>
    );
}

export default Review;
